<style>
.flow-shell{margin:-33px -35px -60px;min-height:calc(100vh - 77px);background:#f8fafc;display:flex;flex-direction:column}
.flow-head{height:68px;background:#fff;border-bottom:1px solid var(--ot-line);display:flex;align-items:center;justify-content:space-between;padding:0 24px;gap:16px;z-index:5}.flow-head h1{font-size:16px;margin:0}.flow-head small{color:var(--ot-muted);font-size:11px}.flow-head-actions{display:flex;align-items:center;gap:8px}.save-state{font-size:11px;color:var(--ot-success);padding:7px 10px;border-radius:99px;background:#edf9f4}.save-state.dirty{color:var(--ot-warning);background:#fff7e8}.flow-body{display:grid;grid-template-columns:230px minmax(0,1fr) 310px;min-height:calc(100vh - 145px);overflow:hidden}.flow-palette,.flow-inspector{background:#fff;padding:18px;border-inline-start:1px solid var(--ot-line);overflow:auto}.flow-palette{border-inline-start:0;border-inline-end:1px solid var(--ot-line)}.flow-palette h2,.flow-inspector h2{font-size:14px;margin:0 0 5px}.flow-palette p,.flow-inspector .hint{font-size:11px;color:var(--ot-muted);margin:0 0 16px}.node-pick{display:flex;align-items:center;gap:10px;width:100%;border:1px solid var(--ot-line);background:#fff;border-radius:12px;padding:11px;margin:7px 0;text-align:right;transition:.18s}.node-pick:hover{border-color:var(--ot-red);background:var(--ot-red-soft);transform:translateX(-2px)}.node-pick i{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:#fff0f1;color:var(--ot-red);font-style:normal}.node-pick b{font-size:12px;display:block}.node-pick small{font-size:10px;color:var(--ot-muted)}.flow-canvas-wrap{position:relative;overflow:hidden;background-color:#fbfcfd;background-image:radial-gradient(#d8dde5 .7px,transparent .7px);background-size:22px 22px}.flow-canvas{position:absolute;inset:0;transform-origin:0 0;min-width:1600px;min-height:1000px}.flow-edges{position:absolute;inset:0;pointer-events:none;width:1600px;height:1000px}.flow-edge{stroke:#9aa6b2;stroke-width:2;fill:none;marker-end:url(#arrow)}.flow-edge.condition{stroke:var(--ot-red);stroke-dasharray:6 4}.flow-node{position:absolute;width:220px;background:#fff;border:1px solid #dfe4ea;border-radius:15px;box-shadow:0 8px 25px rgba(31,41,55,.08);cursor:grab;user-select:none}.flow-node.selected{border:2px solid var(--ot-red);box-shadow:0 0 0 4px #d5222c18,0 12px 30px rgba(31,41,55,.12)}.flow-node .node-top{display:flex;align-items:center;gap:8px;padding:12px 13px;border-bottom:1px solid #eef1f4}.node-icon{width:27px;height:27px;border-radius:8px;background:#fff0f1;color:var(--ot-red);display:grid;place-items:center}.flow-node .node-top b{font-size:12px}.flow-node .node-body{padding:11px 13px;color:#697586;font-size:11px;line-height:1.7;min-height:40px}.flow-node .node-port{position:absolute;width:10px;height:10px;border:2px solid #fff;border-radius:50%;background:var(--ot-red);top:50%;transform:translateY(-50%);box-shadow:0 0 0 1px var(--ot-red)}.flow-node .in{right:-6px}.flow-node .out{left:-6px}.flow-node.start .node-icon{background:#edf9f4;color:var(--ot-success)}.flow-node.end .node-icon{background:#f0f2f5;color:#44515f}.flow-node.condition .node-icon{background:#eef4ff;color:var(--ot-info)}.flow-node.action .node-icon{background:#fff5e7;color:var(--ot-warning)}.node-label{position:absolute;left:50%;top:-29px;transform:translateX(-50%);white-space:nowrap;background:#151b23;color:#fff;border-radius:99px;font-size:10px;padding:4px 10px;display:none}.flow-node:hover .node-label{display:block}.canvas-toolbar{position:absolute;bottom:18px;right:18px;display:flex;gap:4px;background:#fff;border:1px solid var(--ot-line);border-radius:12px;padding:5px;box-shadow:0 8px 24px #10182812;z-index:4}.canvas-toolbar button{border:0;background:transparent;border-radius:8px;padding:8px 10px;color:#526170;font-weight:700}.canvas-toolbar button:hover{background:var(--ot-red-soft);color:var(--ot-red)}.inspector-empty{text-align:center;padding:55px 10px;border:1px dashed #d7dde5;border-radius:14px;color:var(--ot-muted);font-size:12px}.inspector-section{border-top:1px solid #edf0f3;padding-top:15px;margin-top:15px}.inspector-section label{font-size:11px;font-weight:700;display:block;margin-bottom:5px}.flow-error{margin:15px 18px 0;position:absolute;z-index:6;left:0;right:0}.flow-loading{position:absolute;inset:0;display:grid;place-items:center;background:#ffffffcc;z-index:10}.flow-mobile-tabs{display:none}
@media(max-width:1100px){.flow-body{grid-template-columns:200px minmax(0,1fr) 280px}.flow-palette{padding:12px}.flow-inspector{padding:12px}}
