<div class="flow-shell" id="flowApp" data-flow-id="{{ $flow->id }}" data-revision-id="{{ $revision->id }}" data-save-url="{{ route('app.flow.save',['workspace'=>$workspace->slug,'agent'=>$agent->id]) }}" data-validate-url="{{ route('app.flow.validate',['workspace'=>$workspace->slug,'agent'=>$agent->id]) }}" data-publish-url="{{ route('app.flow.publish',['workspace'=>$workspace->slug,'agent'=>$agent->id]) }}">
<header class="flow-head"><div style="display:flex;align-items:center;gap:12px"><a href="{{ route('app.agents.show',['workspace'=>$workspace->slug,'agent'=>$agent->id]) }}" class="btn btn-outline btn-sm">رجوع</a><div><h1>عقل الوكيل: {{ $agent->name }}</h1><small>المسار الرئيسي · v{{ $revision->version }} · <span class="demo-chip">محلي</span></small></div></div><div class="flow-head-actions"><span class="save-state" id="saveState">محفوظ</span><button class="btn btn-outline btn-sm" id="validateBtn">تحقق</button><button class="btn btn-primary btn-sm" id="publishBtn">نشر المسار</button></div></header>
<div class="flow-mobile-tabs"><button id="paletteTab">العقد</button><button class="active">المسار</button><button id="inspectorTab">الإعدادات</button></div>
<div class="flow-body"><aside class="flow-palette" id="palette"><h2>عقد المسار</h2><p>اسحب أو اضغط لإضافة عقدة إلى اللوحة.</p><button class="node-pick" data-add="message"><i>✦</i><span><b>رسالة</b><small>رد أو ترحيب</small></span></button><button class="node-pick" data-add="condition"><i>◇</i><span><b>شرط</b><small>تفريع حسب الحالة</small></span></button><button class="node-pick" data-add="action"><i>↗</i><span><b>إجراء</b><small>Smart Action</small></span></button><button class="node-pick" data-add="handoff"><i>♧</i><span><b>موظف</b><small>Human takeover</small></span></button><button class="node-pick" data-add="end"><i>○</i><span><b>نهاية</b><small>إنهاء المسار</small></span></button><div class="alert" style="margin-top:22px">المسار الحالي Draft. لا يوجد تشغيل AI حي بدون مزود OnTrack مُختبر.</div></aside>
<main class="flow-canvas-wrap" id="canvasWrap"><div class="flow-error" id="flowError"></div><div class="flow-canvas" id="canvas"><svg class="flow-edges" id="edgesSvg" viewBox="0 0 1600 1000"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#9aa6b2"/></marker></defs></svg></div><div class="canvas-toolbar"><button id="zoomOut">−</button><button id="zoomValue">100%</button><button id="zoomIn">+</button><button id="fitBtn">ملاءمة</button><button id="resetBtn">↺</button></div></main>
<aside class="flow-inspector" id="inspector"><h2>خصائص العقدة</h2><p class="hint">حدد عقدة لتعديل اسمها ووصفها وإعدادها.</p><div id="inspectorContent"><div class="inspector-empty">اختر عقدة من المسار لعرض إعداداتها.</div></div></aside></div></div>
<script>
(function(){
 const app=document.getElementById('flowApp'), canvas=document.getElementById('canvas'), wrap=document.getElementById('canvasWrap'), svg=document.getElementById('edgesSvg'), stateEl=document.getElementById('saveState'), errorEl=document.getElementById('flowError');
 let zoom=1, selected=null, dirty=false;
 let nodes=[{id:'start',type:'start',title:'بداية',description:'نقطة دخول المحادثة',x:620,y:90,config:{}},{id:'greeting',type:'message',title:'ترحيب',description:'عرّف الوكيل بنفسه واسأل عن احتياج العميل.',x:620,y:270,config:{content:'أهلًا، كيف يمكنني مساعدتك؟'}},{id:'end',type:'end',title:'نهاية',description:'إنهاء المسار بأمان',x:620,y:500,config:{}}];
 let edges=[{source:'start',target:'greeting',label:'بدء'},{source:'greeting',target:'end',label:'لا توجد خطوة أخرى'}];
 const icons={start:'⚑',message:'✦',condition:'◇',action:'↗',handoff:'♧',end:'○'};
 function markDirty(){dirty=true;stateEl.textContent='تغييرات غير محفوظة';stateEl.classList.add('dirty')}
 function render(){document.querySelectorAll('.flow-node').forEach(n=>n.remove()); svg.querySelectorAll('.flow-edge').forEach(e=>e.remove()); nodes.forEach(n=>{const el=document.createElement('div');el.className='flow-node '+n.type+(selected===n.id?' selected':'');el.dataset.id=n.id;el.style.left=n.x+'px';el.style.top=n.y+'px';el.innerHTML='<span class="node-label">'+(n.type==='condition'?'مسار شرطي':'')+'</span><span class="node-port in"></span><div class="node-top"><span class="node-icon">'+(icons[n.type]||'✦')+'</span><b>'+escapeHtml(n.title)+'</b></div><div class="node-body">'+escapeHtml(n.description||'أضف وصفًا لهذه العقدة.')+'</div><span class="node-port out"></span>';el.addEventListener('click',e=>{e.stopPropagation();selected=n.id;renderInspector();render()});makeDraggable(el,n);canvas.appendChild(el)});edges.forEach(edge=>{const a=nodes.find(n=>n.id===edge.source),b=nodes.find(n=>n.id===edge.target);if(!a||!b)return;const line=document.createElementNS('http://www.w3.org/2000/svg','path');line.classList.add('flow-edge');line.setAttribute('d',`M ${a.x+110} ${a.y+75} C ${a.x+110} ${a.y+120}, ${b.x+110} ${b.y-30}, ${b.x+110} ${b.y}`);svg.appendChild(line)});applyTransform()}
 function makeDraggable(el,node){let down=false,ox=0,oy=0;el.addEventListener('pointerdown',e=>{down=true;ox=e.clientX-node.x*zoom;oy=e.clientY-node.y*zoom;el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!down)return;node.x=Math.max(10,(e.clientX-ox)/zoom);node.y=Math.max(10,(e.clientY-oy)/zoom);el.style.left=node.x+'px';el.style.top=node.y+'px';drawEdges();markDirty()});el.addEventListener('pointerup',()=>{down=false})}
 function drawEdges(){svg.querySelectorAll('.flow-edge').forEach(e=>e.remove());edges.forEach(edge=>{const a=nodes.find(n=>n.id===edge.source),b=nodes.find(n=>n.id===edge.target);if(!a||!b)return;const line=document.createElementNS('http://www.w3.org/2000/svg','path');line.classList.add('flow-edge');line.setAttribute('d',`M ${a.x+110} ${a.y+75} C ${a.x+110} ${a.y+120}, ${b.x+110} ${b.y-30}, ${b.x+110} ${b.y}`);svg.appendChild(line)})}
 function applyTransform(){canvas.style.transform=`scale(${zoom})`;document.getElementById('zoomValue').textContent=Math.round(zoom*100)+'%'}
 function renderInspector(){const box=document.getElementById('inspectorContent'),n=nodes.find(x=>x.id===selected);if(!n){box.innerHTML='<div class="inspector-empty">اختر عقدة من المسار لعرض إعداداتها.</div>';return}box.innerHTML='<div class="inspector-section"><label>اسم العقدة</label><input class="input" id="nodeTitle" value="'+escapeAttr(n.title)+'"><label style="margin-top:12px">الوصف</label><textarea class="input" id="nodeDesc" rows="4">'+escapeHtml(n.description||'')+'</textarea><label style="margin-top:12px">النص/الإعداد</label><textarea class="input" id="nodeConfig" rows="5">'+escapeHtml(n.config?.content||'')+'</textarea><button class="btn btn-primary" id="applyNode" style="margin-top:14px;width:100%">تطبيق التعديلات</button><button class="btn btn-outline" id="deleteNode" style="margin-top:8px;width:100%">حذف العقدة</button></div>';document.getElementById('applyNode').onclick=()=>{n.title=document.getElementById('nodeTitle').value;n.description=document.getElementById('nodeDesc').value;n.config={content:document.getElementById('nodeConfig').value};markDirty();render()};document.getElementById('deleteNode').onclick=()=>{if(n.type==='start'){showError('لا يمكن حذف عقدة البداية.');return}nodes=nodes.filter(x=>x.id!==n.id);edges=edges.filter(e=>e.source!==n.id&&e.target!==n.id);selected=null;markDirty();renderInspector();render()}}
 function addNode(type){const id=type+'_'+Date.now();nodes.push({id,type,title:{message:'رسالة جديدة',condition:'شرط جديد',action:'إجراء جديد',handoff:'تحويل لموظف',end:'نهاية'}[type],description:'انقر لتعديل هذه العقدة.',x:430+Math.random()*350,y:180+Math.random()*450,config:{}});selected=id;markDirty();renderInspector();render()}
 function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function escapeAttr(s){return escapeHtml(s)}function showError(msg){errorEl.innerHTML='<div class="alert" role="alert">'+escapeHtml(msg)+'</div>';setTimeout(()=>errorEl.innerHTML='',4500)}
 document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>addNode(b.dataset.add)));document.getElementById('zoomIn').onclick=()=>{zoom=Math.min(1.7,zoom+.1);applyTransform()};document.getElementById('zoomOut').onclick=()=>{zoom=Math.max(.55,zoom-.1);applyTransform()};document.getElementById('resetBtn').onclick=()=>{zoom=1;applyTransform()};document.getElementById('fitBtn').onclick=()=>{zoom=.85;applyTransform()};document.getElementById('validateBtn').onclick=async()=>{const r=await fetch(app.dataset.validateUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''},body:JSON.stringify({nodes,edges})});const data=await r.json();if(!data.valid)showError(data.errors.join(' — '));else{stateEl.textContent='المسار صالح للنشر';stateEl.classList.remove('dirty')}};document.getElementById('publishBtn').onclick=async()=>{const r=await fetch(app.dataset.publishUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''},body:JSON.stringify({flow_id:app.dataset.flowId})});const data=await r.json();if(!r.ok)showError((data.errors||['تعذر النشر']).join(' — '));else{dirty=false;stateEl.textContent='تم نشر المسار';stateEl.classList.remove('dirty')}};canvas.addEventListener('click',()=>{selected=null;renderInspector();render()});document.getElementById('paletteTab').onclick=()=>document.getElementById('palette').classList.toggle('open');document.getElementById('inspectorTab').onclick=()=>document.getElementById('inspector').classList.toggle('open');renderInspector();render();
})();
</script>
@endsection